/** Bind the body and refuse it before anything is read or written: a signed-in user, a clerk limit (when given)
 *  that is blank (no limit) or an amount 0.00 or more with up to two decimals, and a floor (when given) that is an
 *  amount 0.00 or more with up to two decimals, and terms (when given) that
 *  are a whole number of days, and a late percent (when given) that is a percent 0.00 or more with up to two decimals, and a policy date (when given) that is
 *  blank (the sheet's today) or a date yyyy-mm-dd, and a period numbering from (when given) that is blank (off) or a date yyyy-mm-dd, and grades' own terms (when given)
 *  only for grades A, B or C, and a cap and a proof threshold (when given) each blank (none) or an amount 0.00 or more with up to two decimals, each blank (none: the sheet's terms) or a whole number of days, and from-dates (when given) only for the dated settings, each blank (the sheet's
 *  today) or a date yyyy-mm-dd, and permission entries (when given) only for open, settle, void, reassign, close or
 *  reopen, each blank (the standing rule) or a comma separated list of clerk and steward, and grace days (when given) blank (off) or a whole number of days, and a note threshold (when given) blank (none) or an amount 0.00 or more with up to two decimals, and an entry date (when given) blank (off) or a date yyyy-mm-dd, and grades' grace (when given) only for grades A, B or C, each blank (none) or a whole number of days, and a pot (when given) blank (none) or an amount 0.00 or more with up to two decimals. A fiscal year start month (when given) is a month 1 to 12. The parent sheet (when given) is
 *  checked against the store by ValidateParent. */
public class ValidateSettings {
    /** The grades that may have terms of their own. */
    static final List<String> GRADES = List.of("A", "B", "C");

    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSettingException("Sign in before changing settings.");
        }
        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
        }
        String floor = request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.matches(AMOUNT)) {
            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.matches("\\d{1,4}")) {
            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
        }
        String latePct = request.latePct() == null ? null : request.latePct().trim();
        if (latePct != null && !latePct.matches(PERCENT)) {
            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
        }
        String policy = request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
            }
        }
        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
            }
        }
        String cap = request.cap() == null ? null : request.cap().trim();
        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String threshold = request.proofThreshold() == null ? null : request.proofThreshold().trim();
        if (threshold != null && !threshold.isEmpty() && !threshold.matches(AMOUNT)) {
            throw new InvalidSettingException("The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String noteThreshold = request.noteThreshold() == null ? null : request.noteThreshold().trim();
        if (noteThreshold != null && !noteThreshold.isEmpty() && !noteThreshold.matches(AMOUNT)) {
            throw new InvalidSettingException("The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String grace = request.graceDays() == null ? null : request.graceDays().trim();
        if (grace != null && !grace.isEmpty() && !grace.matches("\\d{1,4}")) {
            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank for off.");
        }
        String entered = request.entryDate() == null ? null : request.entryDate().trim();
        LocalDate entryDate = null;
        if (entered != null && !entered.isEmpty()) {
            try {
                entryDate = LocalDate.parse(entered);
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The entry date must be a date, yyyy-mm-dd, or blank for off.");
            }
        }
        String pot = request.pot() == null ? null : request.pot().trim();
        if (pot != null && !pot.isEmpty() && !pot.matches(AMOUNT)) {
            throw new InvalidSettingException("The pot must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
        }
        String alert = request.alertThreshold() == null ? null : request.alertThreshold().trim();
        if (alert != null && !alert.isEmpty() && !alert.matches(AMOUNT)) {
            throw new InvalidSettingException("The alert threshold must be an amount, 0.00 or more, with up to two decimals, or blank for off.");
        }
        String parent = request.parent() == null ? null : request.parent().trim();
        String fiscal = request.fiscalStartMonth() == null ? null : request.fiscalStartMonth().trim();
        if (fiscal != null && !fiscal.matches("[1-9]|1[0-2]")) {
            throw new InvalidSettingException("The fiscal year start month must be a month, 1 to 12.");
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        if (request.gradeTerms() != null) {
            for (String grade : request.gradeTerms().keySet()) {
                if (!GRADES.contains(grade)) {
                    throw new InvalidSettingException("Terms may be set only for grade A, B or C.");
                }
            }
            for (String grade : GRADES) {
                if (!request.gradeTerms().containsKey(grade)) {
                    continue;
                }
                String days = request.gradeTerms().get(grade) == null ? "" : request.gradeTerms().get(grade).trim();
                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
                    throw new InvalidSettingException("The terms of grade " + grade
                            + " must be a whole number of days, 0 or more, or blank for the sheet's terms.");
                }
                gradeTerms.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
            }
        }
        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
        if (request.gradeGrace() != null) {
            for (String grade : request.gradeGrace().keySet()) {
                if (!GRADES.contains(grade)) {
                    throw new InvalidSettingException("Grace may be set only for grade A, B or C.");
                }
            }
            for (String grade : GRADES) {
                if (!request.gradeGrace().containsKey(grade)) {
                    continue;
                }
                String days = request.gradeGrace().get(grade) == null ? "" : request.gradeGrace().get(grade).trim();
                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
                    throw new InvalidSettingException("The grace of grade " + grade
                            + " must be a whole number of days, 0 or more, or blank for none.");
                }
                gradeGrace.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
            }
        }
        Map<String, BigDecimal> gradeProofThreshold = new LinkedHashMap<>();
        if (request.gradeProofThreshold() != null) {
            for (String grade : request.gradeProofThreshold().keySet()) {
                if (!GRADES.contains(grade)) {
                    throw new InvalidSettingException("A proof threshold may be set only for grade A, B or C.");
                }
            }
            for (String grade : GRADES) {
                if (!request.gradeProofThreshold().containsKey(grade)) {
                    continue;
                }
                String amount = request.gradeProofThreshold().get(grade) == null ? ""
                        : request.gradeProofThreshold().get(grade).trim();
                if (!amount.isEmpty() && !amount.matches(AMOUNT)) {
                    throw new InvalidSettingException("The proof threshold of grade " + grade
                            + " must be an amount, 0.00 or more, with up to two decimals, or blank for the sheet's.");
                }
                gradeProofThreshold.put(grade, amount.isEmpty() ? null : new BigDecimal(amount).setScale(2));
            }
        }
        Map<String, String> perms = new LinkedHashMap<>();
        if (request.perms() != null) {
            for (String action : request.perms().keySet()) {
                if (!Permissions.ACTIONS.contains(action)) {
                    throw new InvalidSettingException("Permissions may be set only for open, settle, void, reassign, close or reopen.");
                }
            }
            for (String action : Permissions.ACTIONS) {
                if (!request.perms().containsKey(action)) {
                    continue;
                }
                String entry = request.perms().get(action) == null ? "" : request.perms().get(action).trim();
                List<String> roles = new ArrayList<>();
                if (!entry.isEmpty()) {
                    for (String role : entry.split(",", -1)) {
                        String r = role.trim();
                        if (!r.equals(Role.CLERK) && !r.equals(Role.STEWARD)) {
                            throw new InvalidSettingException("The roles allowed to " + action
                                    + " must be a comma separated list of clerk and steward, or blank for the standing rule.");
                        }
                        if (!roles.contains(r)) {
                            roles.add(r);
                        }
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
        Map<String, LocalDate> from = new LinkedHashMap<>();
        if (request.from() != null) {
            for (var e : request.from().entrySet()) {
                if (!SettingHistory.KEYS.contains(e.getKey())) {
                    throw new InvalidSettingException("Only a setting that carries a figure takes a from-date.");
                }
                String date = e.getValue() == null ? "" : e.getValue().trim();
                if (date.isEmpty()) {
                    continue;
                }
                try {
                    from.put(e.getKey(), LocalDate.parse(date));
                } catch (DateTimeParseException ex) {
                    throw new InvalidSettingException("The from-date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
                }
            }
        }
        body.set(new SettingsInput(request.user().trim(), limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : new BigDecimal(floor).setScale(2),
                terms == null ? null : Integer.valueOf(terms),
                latePct == null ? null : new BigDecimal(latePct).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from,
                threshold != null, threshold == null || threshold.isEmpty() ? null : new BigDecimal(threshold).setScale(2),
                perms, grace != null, grace == null || grace.isEmpty() ? null : Integer.valueOf(grace),
                noteThreshold != null,
                noteThreshold == null || noteThreshold.isEmpty() ? null : new BigDecimal(noteThreshold).setScale(2),
                entered != null, entryDate, gradeGrace, gradeProofThreshold,
                pot != null, pot == null || pot.isEmpty() ? null : new BigDecimal(pot).setScale(2),
                parent != null, parent == null || parent.isEmpty() ? null : parent,
                fiscal == null ? null : Integer.valueOf(fiscal),
                alert != null, alert == null || alert.isEmpty() ? null : new BigDecimal(alert).setScale(2)));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's settings: the dated ones (see SettingHistory) one value per key and from-date, the policy date and
 *  the period numbering from (not dated) on the sheet's row. */
@Repository
public class SettingRepository {

    /** The floor of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms of a sheet before any are in force. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings in force on its today. */
    public Settings of(String sheetId) {
        return of(sheetId, history(sheetId), today(sheetId));
    }

    /** The sheet's settings as they stood at the end of the day, in force on it: its dated settings then (see
     *  historyAsOf); the ones that are not dated as they are now. */
    public Settings asOf(String sheetId, LocalDate end) {
        return of(sheetId, historyAsOf(sheetId, end), end);
    }

    private Settings of(String sheetId, SettingHistory history, LocalDate today) {
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.gradeTermsOn(grade, today);
            if (days != null) {
                gradeTerms.put(grade, days);
            }
        }
        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.graceOn(grade, today);
            if (days != null) {
                gradeGrace.put(grade, days);
            }
        }
        Map<String, BigDecimal> gradeProofThreshold = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            BigDecimal amount = history.gradeProofThresholdOn(grade, today);
            if (amount != null) {
                gradeProofThreshold.put(grade, amount);
            }
        }
        return new Settings(sheetId, history.clerkLimitOn(today), history.floorOn(today), history.termsOn(today),
                history.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), gradeTerms,
                history.capOn(today), history.proofThresholdOn(today), history.noteThresholdOn(today), history, permissions(sheetId), graceDays(sheetId),
                entryDate(sheetId), gradeGrace, gradeProofThreshold, pot(sheetId), parent(sheetId),
                fiscalStartMonth(sheetId), alertThreshold(sheetId));
    }

    /** Every value of the sheet's dated settings, by key and from-date. */
    public SettingHistory history(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, val FROM setting_value WHERE sheet_id = ?", rs -> {
            values.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
                    .put(rs.getObject(2, LocalDate.class), rs.getString(3));
        }, sheetId);
        return new SettingHistory(values);
    }

    /** Record the dated setting's value (null: blank) from the from-date, replacing any it had from that date. */
    public void setDated(String sheetId, String key, String value, LocalDate from) {
        jdbc.update("DELETE FROM setting_value WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, from);
        jdbc.update("INSERT INTO setting_value (sheet_id, setting_key, from_date, val) VALUES (?, ?, ?, ?)",
                sheetId, key, from, value);
        jdbc.update("INSERT INTO setting_log (sheet_id, setting_key, from_date, val, made_on) VALUES (?, ?, ?, ?, "
                + "(SELECT today FROM sheet WHERE id = ?))", sheetId, key, from, value, sheetId);
    }

    /** The sheet's dated settings as they stood at the end of the day: each value recorded from a from-date replaces
     *  the one recorded before it for the key from that same date. */
    public SettingHistory historyAsOf(String sheetId, LocalDate end) {
        Map<String, NavigableMap<LocalDate, String>> values = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, val FROM setting_log WHERE sheet_id = ? "
                + "AND (made_on IS NULL OR made_on <= ?) ORDER BY id", rs -> {
                    values.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
                            .put(rs.getObject(2, LocalDate.class), rs.getString(3));
                }, sheetId, end);
        return new SettingHistory(values);
    }

    /** The sheet's clerk limit in force on its today: two decimals, or null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return history(sheetId).clerkLimitOn(today(sheetId));
    }

    /** The sheet's cap in force on its today: two decimals, or null when there is none; a person's due-total is at
     *  most it. */
    public BigDecimal cap(String sheetId) {
        return history(sheetId).capOn(today(sheetId));
    }

    /** The sheet's proof threshold by date (null on a date when there is none then): a claim whose due is above the one
     *  in force on its date cannot be settled or approved while it has no proofs. */
    public DatedAmount proofThreshold(String sheetId) {
        return history(sheetId)::proofThresholdOn;
    }

    /** The proof threshold a claim of the grade dated on the date has: the grade's own in force then when it has one,
     *  else the sheet's in force then; null when there is none. */
    public BigDecimal proofThresholdFor(String sheetId, String grade, LocalDate date) {
        return history(sheetId).proofThresholdFor(grade, date);
    }

    /** The sheet's note threshold by date (null on a date when there is none then): a claim whose due is above the one
     *  in force on its date cannot be opened while its note is empty. */
    public DatedAmount noteThreshold(String sheetId) {
        return history(sheetId)::noteThresholdOn;
    }

    /** The sheet's floor by date: a claim's live due is at least the floor in force on its date. */
    public DatedAmount floor(String sheetId) {
        return history(sheetId)::floorOn;
    }

    /** The sheet's late percent by date: an overdue claim gains, for each full 30 days, the one in force on that
     *  boundary date, of its figure. */
    public DatedAmount latePct(String sheetId) {
        return history(sheetId)::latePctOn;
    }

    /** The terms in days a claim of the grade dated on the date gets: the grade's own in force then, else the
     *  sheet's in force then. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return history(sheetId).termsFor(grade, date);
    }

    /** The sheet's permission matrix: the roles each action is open to. */
    public Permissions permissions(String sheetId) {
        Map<String, String> roles = new HashMap<>();
        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
                rs -> {
                    roles.put(rs.getString(1), rs.getString(2));
                }, sheetId);
        return new Permissions(roles);
    }

    /** Set the roles the action is open to (blank: the standing rule). */
    public void setPermission(String sheetId, String action, String roles) {
        jdbc.update("DELETE FROM sheet_permission WHERE sheet_id = ? AND action = ?", sheetId, action);
        if (!roles.isEmpty()) {
            jdbc.update("INSERT INTO sheet_permission (sheet_id, action, roles) VALUES (?, ?, ?)", sheetId, action, roles);
        }
    }

    /** The sheet's policy date: null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String sheetId) {
        return jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's period numbering from: null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's entry date: null when blank (off: a new claim given no date is dated the sheet's today). */
    public LocalDate entryDate(String sheetId) {
        return jdbc.query("SELECT entry_date FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setEntryDate(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET entry_date = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's pot: null when blank (none). */
    public BigDecimal pot(String sheetId) {
        return jdbc.query("SELECT pot FROM sheet WHERE id = ?",
                rs -> rs.next() && rs.getBigDecimal(1) != null ? rs.getBigDecimal(1).setScale(2) : null, sheetId);
    }

    public void setPot(String sheetId, BigDecimal pot) {
        jdbc.update("UPDATE sheet SET pot = ? WHERE id = ?", pot, sheetId);
    }

    /** The sheet's alert threshold: null when blank (off). */
    public BigDecimal alertThreshold(String sheetId) {
        return jdbc.query("SELECT alert_threshold FROM sheet WHERE id = ?",
                rs -> rs.next() && rs.getBigDecimal(1) != null ? rs.getBigDecimal(1).setScale(2) : null, sheetId);
    }

    public void setAlertThreshold(String sheetId, BigDecimal threshold) {
        jdbc.update("UPDATE sheet SET alert_threshold = ? WHERE id = ?", threshold, sheetId);
    }

    /** The sheet's parent sheet: null when there is none. */
    public String parent(String sheetId) {
        return jdbc.query("SELECT parent FROM sheet WHERE id = ?", rs -> rs.next() ? rs.getString(1) : null, sheetId);
    }

    /** The sheets naming this sheet as their parent, by id. */
    public List<String> children(String sheetId) {
        return jdbc.queryForList("SELECT id FROM sheet WHERE parent = ? ORDER BY id", String.class, sheetId);
    }

    public void setParent(String sheetId, String parent) {
        jdbc.update("UPDATE sheet SET parent = ? WHERE id = ?", parent, sheetId);
    }

    /** The sheet's fiscal year start month, 1 to 12 (1 unless set). */
    public int fiscalStartMonth(String sheetId) {
        Integer month = jdbc.query("SELECT fiscal_start_month FROM sheet WHERE id = ?",
                rs -> rs.next() ? (Integer) rs.getObject(1, Integer.class) : null, sheetId);
        return month != null ? month : 1;
    }

    public void setFiscalStartMonth(String sheetId, int month) {
        jdbc.update("UPDATE sheet SET fiscal_start_month = ? WHERE id = ?", month, sheetId);
    }

    /** The sheet's grace days: null when blank (off). */
    public Integer graceDays(String sheetId) {
        return jdbc.query("SELECT grace_days FROM sheet WHERE id = ?",
                rs -> rs.next() ? (Integer) rs.getObject(1, Integer.class) : null, sheetId);
    }

    public void setGraceDays(String sheetId, Integer days) {
        jdbc.update("UPDATE sheet SET grace_days = ? WHERE id = ?", days, sheetId);
    }

    /** The sheet's today: dated settings are shown, and saved by default, as of it. */
    public LocalDate today(String sheetId) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }
}

