import { PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useSnapshots } from './snapshots';

/** The person's snapshot lines, oldest first: the day being left and their due-total on it. */
function PersonSnapshots({ sheetId, person }: { sheetId: string; person: Person }) {
  const lines = (useSnapshots(sheetId).data ?? []).filter((s) => s.personId === person.id);
  return (
    <td>
      <ul>
        {lines.map((s, i) => (
          <li key={i} data-testid="person-snapshot-line">
            {s.day} {s.dueTotal}
          </li>
        ))}
      </ul>
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 24, Component: PersonSnapshots });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A snapshot written for a person when the sheet's today changed: the day being left and their due-total on it. */
export type Snapshot = { personId: number; day: string; dueTotal: string };

export const snapshotsKey = (sheetId: string) => ['sheet', sheetId, 'snapshots'] as const;

/** Every snapshot on the sheet, oldest first. */
export function useSnapshots(sheetId: string) {
  return useQuery({
    queryKey: snapshotsKey(sheetId),
    queryFn: () => getJson<Snapshot[]>(`/api/sheets/${encodeURIComponent(sheetId)}/snapshots`),
  });
}
